import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, step, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Dimensions
  const WIDTH = 2.6;
  const HEIGHT = 0.68;
  const RADIUS = 0.08;
  const BEVEL_DEPTH = 0.03;

  // Colors
  const colorTop = new THREE.Color(0xff4450);
  const colorMid = new THREE.Color(0xff2a38);
  const colorBot = new THREE.Color(0xc1121f);
  const accentColor = new THREE.Color(0xff2a38);

  // Emissive intensity uniform for hover animation
  const emissiveIntensity = uniform(1.6);

  // Create rounded rectangle shape
  const shape = new THREE.Shape();
  const w = WIDTH / 2;
  const h = HEIGHT / 2;
  const r = RADIUS;

  shape.moveTo(-w + r, -h);
  shape.lineTo(w - r, -h);
  shape.quadraticCurveTo(w, -h, w, -h + r);
  shape.lineTo(w, h - r);
  shape.quadraticCurveTo(w, h, w - r, h);
  shape.lineTo(-w + r, h);
  shape.quadraticCurveTo(-w, h, -w, h - r);
  shape.lineTo(-w, -h + r);
  shape.quadraticCurveTo(-w, -h, -w + r, -h);

  // Extrude to create 3D button with bevel
  const extrudeSettings = {
    depth: BEVEL_DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.01,
    bevelSegments: 2,
    steps: 1
  };

  const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geometry.center();

  // TSL Gradient Material
  const colorTopUniform = uniform(colorTop);
  const colorMidUniform = uniform(colorMid);
  const colorBotUniform = uniform(colorBot);
  const accentUniform = uniform(accentColor);

  const uvNode = uv();
  const t = uvNode.y;

  // Gradient: 0.0→0.55 (top to mid), 0.55→1.0 (mid to bottom)
  const lowerT = t.mul(1.818181); // 1/0.55
  const lowerColor = mix(colorTopUniform, colorMidUniform, lowerT);

  const upperT = t.sub(0.55).mul(2.222222); // 1/0.45
  const upperColor = mix(colorMidUniform, colorBotUniform, upperT);

  const useUpper = step(0.55, t);
  const gradientColor = mix(lowerColor, upperColor, useUpper);

  // Hard seam line at 50% face height (0.01 unit band)
  const seamMask = step(0.495, t).mul(step(t, 0.505));
  const finalColor = mix(gradientColor, gradientColor.mul(0.8), seamMask.mul(0.15));

  // Create PBR material
  const material = new MeshStandardNodeMaterial();
  material.colorNode = finalColor;
  material.emissiveNode = accentUniform.mul(emissiveIntensity.mul(0.2));
  material.emissiveIntensity = 1;
  material.roughness = 0.5;
  material.metalness = 0.35;
  material.clearcoat = 0.22;

  const buttonMesh = new THREE.Mesh(geometry, material);
  group.add(buttonMesh);

  // CTA Label text
  const labelText = ctx.fontAtlas.createText('BEGIN COMMISSION', {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.6
  });
  labelText.position.set(0, 0, BEVEL_DEPTH / 2 + 0.02);
  group.add(labelText);

  // Caption text
  const captionText = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.08
  });
  captionText.position.set(0, -HEIGHT / 2 - 0.25, 0.01);
  group.add(captionText);

  // Contact shadow plane
  const shadowGeometry = new THREE.PlaneGeometry(WIDTH * 1.2, HEIGHT * 0.9);
  const shadowMaterial = new MeshStandardNodeMaterial();
  shadowMaterial.colorNode = uniform(new THREE.Color(0x000000));
  shadowMaterial.metalness = 0;
  shadowMaterial.roughness = 1;
  shadowMaterial.transparent = true;
  shadowMaterial.depthWrite = false;

  const shadowPlane = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowPlane.position.set(0, -HEIGHT / 2 - 0.08, -0.02);
  shadowPlane.material.opacity = 0.35;
  group.add(shadowPlane);

  // Mount animation: weighted-settle scale 1.04 → 1.0
  group.scale.set(1.04, 1.04, 1.04);
  const mountTimeline = gsap.timeline();
  mountTimeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)'
  });

  // Interaction handlers
  group.userData = {
    handlers: {
      hover: (isHovering) => {
        if (isHovering) {
          gsap.to(group.position, {
            z: 0.06,
            duration: 0.18,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          });
          gsap.to(emissiveIntensity, {
            value: 2.2,
            duration: 0.18
          });
          gsap.to(shadowPlane.material, {
            opacity: 0.55,
            duration: 0.18
          });
        } else {
          gsap.to(group.position, {
            z: 0,
            duration: 0.18,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          });
          gsap.to(emissiveIntensity, {
            value: 1.6,
            duration: 0.18
          });
          gsap.to(shadowPlane.material, {
            opacity: 0.35,
            duration: 0.18
          });
        }
      },
      press: () => {
        gsap.to(group.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          onComplete: () => {
            gsap.to(group.scale, {
              x: 1,
              y: 1,
              z: 1,
              duration: 0.2,
              ease: 'back.out'
            });
          }
        });
      }
    },
    cleanup: () => {
      mountTimeline.kill();
      gsap.killTweensOf([group, group.scale, group.position, emissiveIntensity, shadowPlane.material]);
      geometry.dispose();
      material.dispose();
      shadowGeometry.dispose();
      shadowMaterial.dispose();
      labelText.traverse((node) => {
        if (node.geometry) node.geometry.dispose();
        if (node.material) node.material.dispose();
      });
      captionText.traverse((node) => {
        if (node.geometry) node.geometry.dispose();
        if (node.material) node.material.dispose();
      });
    }
  };

  return group;
}
